    def restocking_fee_cents(self, order: Order) -> int:
        """12.5% restocking fee for changed-mind returns, 0 otherwise, in cents.

        The fee is a percentage of the refund, so it is rounded to cents the
        same way the shop rounds its other percentage amounts (tax, discounts):
